export function normalizeNigerianPhone(input) {
  if (typeof input !== "string") {
    return null;
  }

  const value = input.replace(/[\s.()-]/g, "");

  if (!/^\+?\d+$/.test(value)) {
    return null;
  }

  const countryPrefix = value.match(/^(?:\+234|00234|234)/);
  let national = value;

  if (countryPrefix) {
    national = value.slice(countryPrefix[0].length);

    // Drop at most one trunk digit after the country code.
    if (national.startsWith("0")) {
      national = national.slice(1);
    }
  } else {
    if (value.startsWith("+")) {
      return null;
    }

    if (value.startsWith("0") && !value.startsWith("00")) {
      national = value.slice(1);
    }
  }

  if (!/^[789][01]\d{8}$/.test(national)) {
    return null;
  }

  return `+234${national}`;
}

export function formatNigerianPhone(input) {
  const normalized = normalizeNigerianPhone(input);

  if (normalized === null) {
    return null;
  }

  const local = `0${normalized.slice(4)}`;
  return `${local.slice(0, 4)} ${local.slice(4, 7)} ${local.slice(7)}`;
}
